RefPtr<ExchangeSimpleListener> listener = new ExchangeSimpleListener(
    [self = RefPtr(this), headersCopy = std::move(headersCopy), requestedIds,
     markRead](const nsTArray<nsCString>& ids,
               bool useLegacyFallback) mutable {
      MOZ_ASSERT(headersCopy.Length() == requestedIds.Length());

      CopyableTArray<RefPtr<nsIMsgDBHdr>> foundHeaders;
      if (requestedIds.Length() == ids.Length()) {
        // Assume all the returned ids are the ones we requested.
        foundHeaders = std::move(headersCopy);
      } else {
        // Not all requested messages were succesfully marked.
        // Find the ones that were.
        nsTHashSet<nsCString> returnedIds(ids.Length());
        for (const auto& id : ids) {
          returnedIds.Insert(id);
        }

        foundHeaders.SetCapacity(ids.Length());
        for (size_t i = 0; i < headersCopy.Length(); ++i) {
          if (returnedIds.Contains(requestedIds[i])) {
            foundHeaders.AppendElement(headersCopy[i]);
          }
        }
      }

      nsresult rv =
          self->nsMsgDBFolder::MarkMessagesRead(foundHeaders, markRead);
      NS_ENSURE_SUCCESS(rv, rv);

      rv = self->GetDatabase();
      if (NS_SUCCEEDED(rv)) {
        self->mDatabase->Commit(nsMsgDBCommitType::kLargeCommit);

let (successes, errors): (Vec<_>, Vec<_>) = response_messages
    .into_iter()
    .map(|r| process_response_message_class(UpdateItem::NAME, r))
    .enumerate()
    .partition(|(_index, result)| result.is_ok());

let successes: ThinVec<nsCString> = successes
    .into_iter()
    .flat_map(|(_, success)| {
        let message = success.expect("partition should only populate this with okays");
        message.items.inner.into_iter()
    })
    .filter_map(|item| item.into_inner_message().item_id)
    .map(|item_id| item_id.id.into())
    .collect();

let ret = if !successes.is_empty() {
    self.listener
        .on_success((successes, UseLegacyFallback::No).into())

// If there were errors, return an aggregated error.
if !errors.is_empty() {
    let num_errs = errors.len();
    let (index, ref first_err) = errors[0];
    let first_error = first_err
        .as_ref()
        .expect_err("partition should only populate this with errs");
    return Err(XpComEwsError::Processing {
        message: format!(
            "response contained {num_errs} errors; the first error (at index {index}) was: {first_error:?}"
        ),
    });
}

Ok(ret?)
